// Deklarasi variabel
const $tabelData = $('#tabelData'),
    $formData = $('#formData'),
    $modalDiv = $('#modalDiv'),
    formCek = CirebonwebForm.FormCek($formData);

function hitungTotal() {
    const subtotal = parseInt($('#subtotal').val()) || 0;
    const ongkir = parseInt($('#ongkir').val()) || 0;
    const total = subtotal + ongkir;

    $('#totalRp').val(CirebonwebFormat.Rupiah(total));
    $('#total').val(total);
}

$(function () {
    $tabelData.DataTable({
        processing: true,
        serverSide: true,
        ajax: {
            url: `${thisUrl}/tabel`,
            type: 'POST',
            data: function (d) { d.filter_supplier = $('#filter_supplier').val(); }
        },
        autoWidth: false,
        responsive: true,
        search: { return: true },
        dom: 'Blfrtip',
        buttons: [
            // { text: 'Add', action: () => { window.location.href = `${thisUrl}/item?add`; } },
            { text: 'Add', action: () => { simpan(); } },
            {
                text: 'Reload',
                action: function (e, dt, node, config) {
                    dt.search('').draw();
                    $('#filter_supplier').val('').trigger('change');

                    Swal.fire({
                        icon: 'success',
                        title: 'Informasi',
                        text: 'Selesai reload tabel ke kondisi awal',
                        showConfirmButton: false,
                        timer: 1300
                    }).then(function () { dt.ajax.reload(null, true); });
                }
            },
            { extend: 'excelHtml5', exportOptions: { columns: ':not(.no-export)', orthogonal: 'export' } }
        ],
        columnDefs: [
            { targets: '_all', className: 'dt-head-center' },
            { targets: [0, 1, 4], className: 'dt-body-center' },
            { targets: [5, 6, 7], className: 'dt-body-right' },
            {
                targets: [5, 6, 7], render: function (data, type, row) {
                    if (type === 'display' || type === 'filter') {
                        return 'Rp ' + CirebonwebFormat.Rupiah(data); // tampil di tabel
                    }
                    return data; // untuk sort & export, kembalikan nilai asli
                }
            },
            { targets: [4, 5, 6, 7], orderable: false }
        ]
    });

    // Custom dropdown filter
    $('#tabelData_filter.dataTables_filter').append($('#filter_supplier'));
    $(document).on('change', '#filter_supplier', function () {
        $tabelData.DataTable().ajax.reload(null, false);
    });

    // Input tanggal
    $('.tanggal').datepicker({
        dateFormat: 'dd-mm-yy',
        onSelect: function () {
            // Mengambil tanggal yang dipilih dan memformat ke yyyy-mm-dd untuk input hidden database
            var mysqlDate = $.datepicker.formatDate('yy-mm-dd', $(this).datepicker('getDate')); $('#' + this.id.replace('_tgl', '')).val(mysqlDate);
        }
    });

    $('#ongkirRp').on('input change', function () {
        let nilai = CirebonwebFormat.unRupiah(this.value);
        this.value = CirebonwebFormat.Rupiah(nilai);
        $('#' + this.id.replace('Rp', '')).val(nilai);
        hitungTotal();
    });

    // Input rupiah
    $('.rupiah').on('input', function () {
        let nilai = CirebonwebFormat.unRupiah($(this).val());
        $(this).val(CirebonwebFormat.Rupiah(nilai));
        const hiddenId = $(this).attr('id').replace('Rp', '');
        $('#' + hiddenId).val(nilai);
    });

    // Fokus select2 input
    $(document).on('select2:open', () => document.querySelector('.select2-container--open .select2-search__field')?.focus());

    // Reset Modal
    $modalDiv.on('shown.bs.modal', function () {
        $('.select2').select2({ dropdownParent: $modalDiv });
        formCek.resetInitial();
    }).on('hidden.bs.modal', function () {
        CirebonwebForm.FormReset(this);
        $('.select2.select2-hidden-accessible').select2('destroy');
    });
});

function simpan(id) {
    const isEdit = id > 0;

    let $modalTitle = $('.modal-title'),
        $btnSubmit = $('#btnSubmit'),
        postUrl = `${thisUrl}/simpan`;

    if (isEdit) {
        CirebonwebForm.FormFetch(`${thisUrl}/getid`, { id }, 'POST', {})
            .done(function (response) {
                if (response.success) {
                    $modalTitle.text('Edit Data');
                    $btnSubmit.text('Update');

                    $formData.find('#id').val(response.data.id);
                    $formData.find('#supplier_id').val(response.data.supplier_id || '').trigger('change');
                    CirebonwebFormat.isoTanggal('tgl_order', response.data.tgl_order);
                    $formData.find('#no_order').val(response.data.no_order);
                    $formData.find('#total_qty').val(response.data.total_qty);
                    $formData.find('#subtotal').val(response.data.subtotal);
                    $formData.find('#ongkir').val(response.data.ongkir);
                    $formData.find('#total').val(response.data.total);
                    $formData.find('#subtotalRp').val(CirebonwebFormat.Rupiah(response.data.subtotal));
                    $formData.find('#ongkirRp').val(CirebonwebFormat.Rupiah(response.data.ongkir));
                    $formData.find('#totalRp').val(CirebonwebFormat.Rupiah(response.data.total));
                    $formData.find('#keterangan').val(response.data.keterangan);
                    $modalDiv.modal('show');
                }
            });
    } else {
        $('#id').val('');
        $('#supplier_id').val('').trigger('change');

        $modalTitle.text('Tambah Data');
        $btnSubmit.text('Simpan');
        $modalDiv.modal('show');
    }

    $formData.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            supplier_id: { required: true, digits: true },
            tgl_order: { date: true },
            no_order: { required: true, maxlength: 50 },
            keterangan: { maxlength: 255 }
        },

        submitHandler: function () {
            if (!formCek.isChanged()) return false;

            CirebonwebForm.FormFetch(postUrl, $formData.serializeArray(), 'POST', {
                before_call: function () {
                    if (!formCek.isChanged()) return false;

                    $btnSubmit
                        .attr('disabled', true)
                        .html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },

                after_call: function () {
                    $btnSubmit.attr('disabled', false).html('Simpan');
                }
            })
                .done(function (response) {
                    if (response.success) {
                        $modalDiv.modal('hide');
                        Swal.fire({ icon: 'success', title: 'Sukses', html: response.messages, showConfirmButton: false, timer: 1300 })
                            .then(function () {
                                if (!isEdit) {
                                    window.location.href = `${thisUrl}/item?edit=${response.data.id}`;
                                } else {
                                    $tabelData.DataTable().ajax.reload(null, false);
                                }
                            });
                    }
                });

            return false;
        }
    }));
}

